<template>
  <div v-if="open" class="wizard-overlay" role="dialog" aria-modal="true" aria-label="Print setup" @click.self="$emit('close')">
    <section class="wizard-modal">
      <header><div><small>Print &amp; CorelDRAW layout</small><h2>{{ collectionName }}</h2></div><button type="button" aria-label="Close print setup" @click="$emit('close')"><i class="bi bi-x-lg"></i></button></header>
      <div class="wizard-body">
        <div class="controls">
          <label>Canvas size<select v-model="paperId"><option v-for="paper in papers" :key="paper.id" :value="paper.id">{{ paper.label }} · {{ paper.width }} × {{ paper.height }} mm</option><option value="custom">Custom canvas…</option></select></label>
          <label>Measurement unit<select v-model="unit"><option value="mm">Millimetres</option><option value="cm">Centimetres</option><option value="in">Inches</option></select></label>
          <template v-if="paperId === 'custom'"><label>Canvas width<input v-model.number="customWidthDisplay" type="number" min="1" step="0.1"><span>{{ unit }}</span></label><label>Canvas height<input v-model.number="customHeightDisplay" type="number" min="1" step="0.1"><span>{{ unit }}</span></label></template>
          <label>Orientation<select v-model="orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label>
          <label>Print sides<select v-model="sides"><option value="single">Single-sided</option><option value="double">Double-sided · flip on long edge</option></select></label>
          <label>Maximum cards per row<select v-model.number="columns"><option v-for="count in 6" :key="count" :value="count">{{ count }}</option></select></label>
          <label>Artwork arrangement<select v-model="grouping"><option value="optimized">Best fit · fewest sheets</option><option value="size">Group matching sizes</option><option value="order">Keep collection order</option></select></label>
          <fieldset class="size-control"><legend>Artwork sizing <span><i class="bi bi-lock-fill"></i> Aspect ratios locked</span></legend><small>The shared artwork remains read-only. Scaling applies proportionally to the whole collection.</small><label class="scale">Collection scale<input v-model.number="scalePercent" type="range" min="25" max="400" step="5"><output>{{ scalePercent }}%</output></label><output>{{ sizeSummary }}</output></fieldset>
          <label>Page margin<input v-model.number="marginDisplay" type="number" min="0" step="0.1"><span>{{ unit }}</span></label>
          <label>Card gap<input v-model.number="gapDisplay" type="number" min="0" step="0.1"><span>{{ unit }}</span></label>
          <label class="check"><input v-model="captions" type="checkbox"> Print card names below artwork</label>
          <fieldset class="finishing"><legend>Finishing</legend><label class="check"><input v-model="registration" type="checkbox"> Add identical registration marks to every production canvas</label><label class="check"><input v-model="cutContour" type="checkbox"> Add a separate CutContour canvas for a cutting plotter</label><div v-if="cutContour"><label>Corner radius<input v-model.number="cornerDisplay" type="number" min="0" step="0.1"><span>{{ unit }}</span></label><label>Cut path offset<input v-model.number="offsetDisplay" type="number" min="-2" max="3" step="0.1"><span>{{ unit }}</span></label></div></fieldset>
        </div>
        <aside class="preview">
          <div class="preview-heading"><span>LIVE PRODUCTION PREVIEW</span><b>{{ layout.pageCount || '—' }} physical sheet{{ layout.pageCount === 1 ? '' : 's' }}</b><small>{{ surfaceCount }} production canvas{{ surfaceCount === 1 ? '' : 'es' }} · {{ sizeSummary }}</small></div>
          <div v-if="!layout.fits" class="layout-error"><i class="bi bi-exclamation-triangle"></i> At least one artwork is larger than this canvas. Reduce the scale or choose a larger canvas.</div>
          <div v-else class="page-list">
            <article v-for="surface in previewSurfaces" :key="`${surface.number}-${surface.kind}`"><header>Sheet {{ surface.number }} · {{ surface.label }} <span>{{ surface.placements.length }} card{{ surface.placements.length === 1 ? '' : 's' }}</span></header><div class="mini-page" :class="{ cut: surface.kind === 'cut' }" :style="{ aspectRatio: `${layout.pageWidth}/${layout.pageHeight}` }"><div v-for="placement in surface.placements" :key="placement.artwork.key" class="mini-card" :class="{ cut: surface.kind === 'cut' }" :style="surface.kind === 'cut' ? cutStyle(placement) : cardStyle(placement, surface.kind === 'back')"><img v-if="surface.kind !== 'cut'" :src="svgDataUrl(placement.artwork.svg)" :alt="placement.artwork.label || 'Print artwork'"></div></div></article>
          </div>
          <p>{{ paper.label }} · {{ orientation }} · {{ sides === 'double' ? 'Duplex' : 'Single-sided' }} · {{ layout.columns }} across<br>{{ layout.pageWidth.toFixed(1) }} × {{ layout.pageHeight.toFixed(1) }} mm canvas{{ cutContour ? ' · vector CutContour page' : '' }}{{ registration ? ' · shared registration marks' : '' }}</p>
        </aside>
      </div>
      <footer><button class="secondary" type="button" @click="$emit('close')">Cancel</button><div><button class="secondary" type="button" :disabled="busy || !layout.fits" @click="downloadPackage"><i class="bi bi-file-earmark-zip"></i> {{ busy ? 'Preparing…' : 'Download CorelDRAW layout' }}</button><button class="primary" type="button" :disabled="busy || !layout.fits" @click="openPrintPreview"><i class="bi bi-printer"></i> Open print preview</button></div></footer>
    </section>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue';
import { packSheets, type PackingGrouping } from '../../features/qrStudio/sheetPacking';
import { createZip } from '../../utils/zip';

export type SharedPrintArtwork = { key?: string; label?: string; svg: string; widthMm?: number; heightMm?: number; format?: string };
type Unit = 'mm' | 'cm' | 'in';
type Placement = { artwork: SharedPrintArtwork & { key: string }; index: number; x: number; mirroredX: number; y: number; width: number; height: number; captionHeight: number };
const props = defineProps<{ open: boolean; collectionName: string; artworks: SharedPrintArtwork[] }>();
defineEmits<{ (event: 'close'): void }>();

const papers = [{ id: 'a3', label: 'A3', width: 297, height: 420 }, { id: 'a4', label: 'A4', width: 210, height: 297 }, { id: 'a5', label: 'A5', width: 148, height: 210 }, { id: 'letter', label: 'US Letter', width: 215.9, height: 279.4 }, { id: 'legal', label: 'US Legal', width: 215.9, height: 355.6 }, { id: 'tabloid', label: 'Tabloid', width: 279.4, height: 431.8 }];
const paperId = ref('a4'), orientation = ref<'portrait' | 'landscape'>('portrait'), sides = ref<'single' | 'double'>('single'), unit = ref<Unit>('mm'), columns = ref(2), grouping = ref<PackingGrouping>('optimized');
const customWidth = ref(210), customHeight = ref(297), scalePercent = ref(100), margin = ref(10), gap = ref(6), captions = ref(true), registration = ref(true), cutContour = ref(true), corner = ref(2), offset = ref(0), busy = ref(false);
const factor = computed(() => unit.value === 'in' ? 25.4 : unit.value === 'cm' ? 10 : 1);
function displayModel(model: typeof margin) { return computed<number>({ get: () => Number((model.value / factor.value).toFixed(unit.value === 'mm' ? 1 : 2)), set: value => { model.value = Math.max(0, Number(value) || 0) * factor.value; } }); }
const customWidthDisplay = displayModel(customWidth), customHeightDisplay = displayModel(customHeight), marginDisplay = displayModel(margin), gapDisplay = displayModel(gap), cornerDisplay = displayModel(corner);
const offsetDisplay = computed<number>({ get: () => Number((offset.value / factor.value).toFixed(unit.value === 'mm' ? 1 : 2)), set: value => { offset.value = (Number(value) || 0) * factor.value; } });
const paper = computed(() => paperId.value === 'custom' ? { id: 'custom', label: 'Custom', width: customWidth.value, height: customHeight.value } : papers.find(item => item.id === paperId.value) || papers[1]);
const page = computed(() => orientation.value === 'portrait' ? { width: paper.value.width, height: paper.value.height } : { width: paper.value.height, height: paper.value.width });
function sourceRatio(svg: string): number { const viewBox = svg.match(/viewBox=["']\s*[\d.-]+\s+[\d.-]+\s+([\d.]+)\s+([\d.]+)["']/i); if (viewBox) return Number(viewBox[1]) / Math.max(1, Number(viewBox[2])); const wh = svg.match(/<svg[^>]*width=["']([\d.]+)[^"']*["'][^>]*height=["']([\d.]+)[^"']*["']/i); return wh ? Number(wh[1]) / Math.max(1, Number(wh[2])) : 1; }
function dimensions(artwork: SharedPrintArtwork) { const ratio = sourceRatio(artwork.svg); const width = Number(artwork.widthMm) > 0 ? Number(artwork.widthMm) : 120; const height = Number(artwork.heightMm) > 0 ? Number(artwork.heightMm) : width / ratio; const scale = Math.max(.05, scalePercent.value / 100); return { width: width * scale, height: height * scale, captionHeight: captions.value ? 6 : 0 }; }
const normalized = computed(() => props.artworks.map((artwork, index) => ({ ...artwork, key: artwork.key || `artwork-${index + 1}` })));
const layout = computed(() => { const packed = packSheets(normalized.value.map((artwork, index) => { const size = dimensions(artwork); return { value: { artwork, index, ...size }, index, width: size.width, height: size.height + size.captionHeight, groupKey: `${size.width.toFixed(2)}x${size.height.toFixed(2)}` }; }), { pageWidth: page.value.width, pageHeight: page.value.height, margin: margin.value, gap: gap.value, maxPerRow: columns.value, grouping: grouping.value }); return { ...packed, pageWidth: page.value.width, pageHeight: page.value.height, pages: packed.pages.map(sheet => ({ number: sheet.number, placements: sheet.items.map(item => ({ ...item.value, x: item.x, mirroredX: page.value.width - item.x - item.value.width, y: item.y, row: item.row })) as Placement[] })) }; });
const sizeSummary = computed(() => { const sizes = normalized.value.map(dimensions); if (!sizes.length) return 'No artwork'; const values = sizes.map(size => `${size.width.toFixed(1)} × ${size.height.toFixed(1)}`); return [...new Set(values)].join(', ') + ' mm'; });
const surfaceCount = computed(() => layout.value.pageCount * (1 + (sides.value === 'double' ? 1 : 0) + (cutContour.value ? 1 : 0)));
const previewSurfaces = computed(() => layout.value.pages.slice(0, 4).flatMap(sheet => [{ ...sheet, kind: 'front', label: 'Front print' }, ...(sides.value === 'double' ? [{ ...sheet, kind: 'back', label: 'Back print · reversed placement' }] : []), ...(cutContour.value ? [{ ...sheet, kind: 'cut', label: 'CutContour · plotter path' }] : [])]));
function cardStyle(item: Placement, mirrored = false) { const x = mirrored ? item.mirroredX : item.x; return { left: `${x / layout.value.pageWidth * 100}%`, top: `${item.y / layout.value.pageHeight * 100}%`, width: `${item.width / layout.value.pageWidth * 100}%`, height: `${item.height / layout.value.pageHeight * 100}%` }; }
function cutStyle(item: Placement) { const inset = offset.value; const width = item.width + inset * 2, height = item.height + inset * 2; return { left: `${(item.x - inset) / layout.value.pageWidth * 100}%`, top: `${(item.y - inset) / layout.value.pageHeight * 100}%`, width: `${width / layout.value.pageWidth * 100}%`, height: `${height / layout.value.pageHeight * 100}%`, borderRadius: item.artwork.format === 'round' ? '50%' : `${Math.max(0, corner.value)}mm` }; }
function svgDataUrl(svg: string) { return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`; }
function safeName(value: string) { return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'print-collection'; }
function escapeXml(value: string) { return value.replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&apos;', '"': '&quot;' })[char] || char); }
function registrationSvg() { if (!registration.value) return ''; const inset = Math.max(2.5, Math.min(7, margin.value / 2)); return [[inset, inset], [layout.value.pageWidth - inset, inset], [inset, layout.value.pageHeight - inset], [layout.value.pageWidth - inset, layout.value.pageHeight - inset]].map(([x,y]) => `<g fill="none" stroke="#000" stroke-width="0.1"><circle cx="${x}" cy="${y}" r="1.2"/><path d="M ${x-2} ${y} H ${x+2} M ${x} ${y-2} V ${y+2}"/></g>`).join(''); }
function surfaceSvg(sheet: typeof layout.value.pages[number], kind: 'front'|'back'|'cut') { const items = sheet.placements.map(item => { if (kind === 'cut') { const x=item.x-offset.value,y=item.y-offset.value,w=item.width+offset.value*2,h=item.height+offset.value*2; return item.artwork.format === 'round' ? `<circle cx="${item.x+item.width/2}" cy="${item.y+item.height/2}" r="${Math.max(.1,Math.min(w,h)/2)}"/>` : `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${corner.value}"/>`; } const x=kind==='back'?item.mirroredX:item.x; return `<image x="${x}" y="${item.y}" width="${item.width}" height="${item.height}" preserveAspectRatio="xMidYMid meet" href="${svgDataUrl(item.artwork.svg)}"/>${captions.value?`<text x="${x+item.width/2}" y="${item.y+item.height+4}" text-anchor="middle" font-family="Arial" font-size="3">${escapeXml(item.artwork.label || '')}</text>`:''}`; }).join(''); const body=kind==='cut'?`<g id="CutContour" fill="none" stroke="#FF00FF" stroke-width="0.0762">${items}</g>`:items; return `<?xml version="1.0"?><svg xmlns="http://www.w3.org/2000/svg" width="${layout.value.pageWidth}mm" height="${layout.value.pageHeight}mm" viewBox="0 0 ${layout.value.pageWidth} ${layout.value.pageHeight}">${body}${registrationSvg()}</svg>`; }
function surfaces() { return layout.value.pages.flatMap(sheet => [{ sheet, kind: 'front' as const }, ...(sides.value === 'double' ? [{ sheet, kind: 'back' as const }] : []), ...(cutContour.value ? [{ sheet, kind: 'cut' as const }] : [])]); }
function downloadBlob(blob: Blob, filename: string) { const url=URL.createObjectURL(blob), link=document.createElement('a'); link.href=url; link.download=filename; link.click(); setTimeout(()=>URL.revokeObjectURL(url),10000); }
function downloadPackage() { busy.value=true; try { const encoder=new TextEncoder(), base=safeName(props.collectionName); const files=surfaces().map(({sheet,kind})=>({name:`${base}-sheet-${String(sheet.number).padStart(2,'0')}-${kind}.svg`,data:encoder.encode(surfaceSvg(sheet,kind))})); normalized.value.forEach((artwork,index)=>files.push({name:`artwork/${String(index+1).padStart(2,'0')}-${safeName(artwork.label||artwork.key)}.svg`,data:encoder.encode(artwork.svg)})); files.push({name:'README.txt',data:encoder.encode('PESHKASH PRINT PACKAGE\r\n\r\nOpen the sheet SVG files directly in CorelDRAW at their original physical dimensions. FRONT and BACK sheets share placement coordinates; BACK placement is reversed for long-edge duplex printing. CutContour sheets use #FF00FF vector paths. Individual source artwork is included in the artwork folder.')}); downloadBlob(createZip(files),`${base}-coreldraw-package.zip`); } finally { busy.value=false; } }
function openPrintPreview() { const popup=window.open('','_blank'); if(!popup)return; const pages=surfaces().map(({sheet,kind})=>`<section class="sheet">${surfaceSvg(sheet,kind)}</section>`).join(''); popup.document.write(`<!doctype html><html><head><title>${escapeXml(props.collectionName)} print</title><style>@page{size:${layout.value.pageWidth}mm ${layout.value.pageHeight}mm;margin:0}html,body{margin:0}.sheet{height:${layout.value.pageHeight}mm;overflow:hidden;page-break-after:always;width:${layout.value.pageWidth}mm}.sheet>svg{display:block;height:100%;width:100%}.sheet:last-child{page-break-after:auto}</style></head><body>${pages}<script>addEventListener('load',()=>setTimeout(()=>print(),150))<\/script></body></html>`); popup.document.close(); }
</script>

<style scoped>
.wizard-overlay{align-items:center;background:#1b1511b8;display:flex;inset:0;justify-content:center;padding:24px;position:fixed;z-index:1400}.wizard-modal{background:#fdfaf6;box-shadow:0 24px 80px #0007;display:flex;flex-direction:column;max-height:94vh;width:min(94vw,1080px)}.wizard-modal>header,.wizard-modal>footer{align-items:center;border-bottom:1px solid #dfd4ca;display:flex;justify-content:space-between;padding:16px 20px}.wizard-modal>header small,.preview-heading>span{color:#ad7d43;font-size:9px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.wizard-modal h2{font:400 22px Rufina,serif;margin:3px 0}.wizard-modal header button{background:transparent;border:0;font-size:18px}.wizard-body{display:grid;gap:24px;grid-template-columns:minmax(0,1fr) 350px;overflow:auto;padding:22px}.controls{align-content:start;display:grid;gap:12px;grid-template-columns:1fr 1fr}.controls label{color:#5f5146;display:grid;font-size:10px;font-weight:700;gap:5px;position:relative;text-transform:uppercase}.controls select,.controls input{background:#fff;border:1px solid #dcd1c7;min-height:40px;padding:8px 10px}.controls label>span{bottom:12px;position:absolute;right:10px}.controls .check{align-items:center;display:flex;grid-column:1/-1;text-transform:none}.controls .check input{min-height:auto}.size-control,.finishing{border:1px solid #d9cdc1;display:grid;gap:10px;grid-column:1/-1;margin:2px 0;padding:12px}.size-control legend,.finishing legend{font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.size-control legend span{color:#8a7767;font-size:9px;font-weight:500;letter-spacing:0;text-transform:none}.size-control small,.size-control>output{color:#806f61;font-size:9px;grid-column:1/-1}.size-control .scale{align-items:center;grid-column:1/-1;grid-template-columns:auto 1fr auto}.size-control .scale input{min-height:auto}.finishing>div{display:grid;gap:10px;grid-template-columns:1fr 1fr}.preview{background:#f1ebe4;display:flex;flex-direction:column;gap:12px;min-height:420px;padding:16px}.preview-heading{display:grid;gap:3px}.preview-heading b{font:400 20px Rufina,serif}.preview-heading small,.preview>p{color:#6e5f53;font-size:10px;line-height:1.5}.page-list{display:grid;gap:10px;max-height:350px;overflow:auto}.page-list article>header{display:flex;font-size:9px;font-weight:700;justify-content:space-between}.mini-page{background:#fff;border:1px solid #d2c5b8;position:relative;width:100%}.mini-card{overflow:hidden;position:absolute}.mini-card img{height:100%;object-fit:fill;width:100%}.mini-page.cut{background:repeating-linear-gradient(45deg,#fff,#fff 7px,#fbf7fb 7px,#fbf7fb 14px)}.mini-card.cut{border:1px solid #f0f;background:transparent}.layout-error{background:#fff3e4;border-left:3px solid #b66d28;color:#744819;font-size:10px;padding:10px}.wizard-modal>footer{border-bottom:0;border-top:1px solid #dfd4ca}.wizard-modal>footer>div{display:flex;gap:8px}.wizard-modal footer button{border:1px solid #b98b51;padding:10px 13px}.secondary{background:#fff;color:#6b5135}.primary{background:#1d1814;color:#fff}.wizard-modal button:disabled{opacity:.45}@media(max-width:760px){.wizard-overlay{padding:0}.wizard-modal{height:100vh;max-height:100vh;width:100vw}.wizard-body{display:block}.preview{margin-top:18px}.wizard-modal>footer{align-items:stretch;gap:8px}.wizard-modal>footer>div{display:grid;flex:1}.controls{grid-template-columns:1fr}}
</style>
